// Decide what each comments-inbox row needs this run: a draft, a status mark, or posting.
const cfg = $('Config').first().json;
const SENSITIVE = /(suicid|kill (my ?self|me)|\bkms\b|end it all|want(ed)? to die|don'?t want to (live|be here)|disappear|self[- ]?harm|cutting myself|overdose|hopeless|can'?t go on|no reason to live|passed away|\bdied\b|funeral|griev|lost my (mum|mom|mother|dad|father|brother|sister|son|daughter|wife|husband|partner|girlfriend|boyfriend|friend|baby|child)|miscarriage|cancer|terminal|abus(e|ed|ive)|\brape|assault|eating disorder|anorex|bulimi|panic attack|depress)/i;
const SPAM = /(https?:\/\/|www\.|\bdm (us|me) for\b|promo(te|tion)?\b|collab\?|check (out )?my (page|profile)|free followers|crypto|onlyfans|\bbitcoin\b)/i;
const TAG_ONLY = /^\s*(@[\w.]+\s*)+$/;
const lower = v => String(v ?? '').trim().toLowerCase();

// Meta can deliver a webhook twice, which leaves duplicate rows. Per comment_id,
// the row that already has a status wins, so a duplicate is never drafted or posted again.
const byId = new Map();
for (const it of $input.all()) {
  const r = it.json;
  const id = String(r.comment_id ?? '').trim();
  if (!id) continue;
  const prev = byId.get(id);
  if (!prev || (!lower(prev.status) && lower(r.status))) byId.set(id, r);
}

const out = [];
let drafts = 0;
for (const [comment_id, r] of byId) {
  const status = lower(r.status);
  const text = String(r.text ?? '');
  if (status === '') {
    if (SENSITIVE.test(text)) {
      out.push({ json: { _action: 'mark', comment_id, status: 'escalate', category: 'sensitive', note: 'Sensitive words found: answer this one yourself' } });
    } else if (!text.trim() || SPAM.test(text) || TAG_ONLY.test(text)) {
      out.push({ json: { _action: 'mark', comment_id, status: 'skip', category: 'spam', note: 'Spam, link or tag-only' } });
    } else if (drafts < Number(cfg.MAX_DRAFTS_PER_RUN)) {
      drafts++;
      out.push({ json: { _action: 'draft', comment_id, text, username: String(r.username ?? ''), media_id: String(r.media_id ?? '') } });
    }
  } else if (status === 'approved' && !String(r.posted_utc ?? '').trim()) {
    const message = String(r.final_reply ?? '').trim() || String(r.draft_reply ?? '').trim();
    if (!message) {
      out.push({ json: { _action: 'mark', comment_id, status: 'escalate', category: String(r.category ?? ''), note: 'Approved but both reply columns are empty' } });
    } else {
      out.push({ json: { _action: 'post', comment_id, message, attempts: Number(r.attempts || 0) } });
    }
  }
}
return out;

// Keep only real sheet columns so the update never invents new ones.
const { comment_id, status, category, note } = $json;
return { json: { comment_id, status, category, note } };

// Turn Claude's answer into the row update. Anything unclear goes to Surafel, never to "approved".
const res = $json;
const now = new Date().toISOString().slice(0, 16);
let action = 'escalate', category = 'other', reply = '', note = '';
if (!res || res.error || !Array.isArray(res.content)) {
  note = 'Drafting failed, answer by hand: ' + JSON.stringify(res?.error ?? res ?? {}).slice(0, 150);
} else if (res.stop_reason === 'refusal') {
  note = 'Claude declined to draft this one, answer by hand';
} else {
  try {
    const block = res.content.find(b => b.type === 'text');
    const j = JSON.parse(block.text);
    action = ['reply', 'escalate', 'skip'].includes(j.action) ? j.action : 'escalate';
    category = String(j.category || 'other');
    reply = String(j.reply || '').trim();
    note = String(j.reason || '');
  } catch (e) {
    note = 'Could not read the draft, answer by hand';
  }
}
// Last checks on the text itself before it reaches the queue.
if (action === 'reply' && (!reply || reply.length > 400 || /https?:\/\/|www\./i.test(reply))) {
  action = 'escalate';
  note = 'Draft was empty, too long or had a link: ' + note;
  reply = '';
}
const status = { reply: 'awaiting_approval', escalate: 'escalate', skip: 'skip' }[action];
return { json: { comment_id: $('What to do?').item.json.comment_id, status, category, draft_reply: reply, note, drafted_utc: now } };

// A reply id back from Meta means it is live. Otherwise count the attempt and stop after three.
const src = $('What to do?').item.json;
const now = new Date().toISOString().slice(0, 16);
if ($json && $json.id) {
  return { json: { comment_id: src.comment_id, status: 'posted', posted_utc: now, reply_id: String($json.id), attempts: src.attempts + 1, note: '' } };
}
const attempts = src.attempts + 1;
const err = $json?.error?.message || $json?.message || JSON.stringify($json ?? {}).slice(0, 150);
return { json: { comment_id: src.comment_id, status: attempts >= 3 ? 'post_failed' : 'approved', attempts, note: 'Post failed (' + attempts + '/3): ' + err } };
